const sharp = require("sharp");
const path = require("path");

// A single downscaled WebP variant per photo, for srcset — the small size
// covers the OtrosProyectos grid card / SwitchImage display width, the
// full-size .webp (already generated by generate-webp.js) covers the
// larger case-study / SafeMap display width.
const targets = [
  "src/Pages/SobreMi/perfil.png",
  "src/Pages/pixelart.png",
  "src/Pages/OtrosProyectos/pastinpixels.jpg",
  "src/Pages/OtrosProyectos/palmotion.jpg",
  "src/Pages/OtrosProyectos/movieselector.jpg",
  "src/Pages/OtrosProyectos/eagles.jpeg",
  "src/Pages/SafeMap/safemap.png",
];

const SMALL_WIDTH = 480;

(async () => {
  for (const rel of targets) {
    const input = path.join(__dirname, "..", rel);
    const output = input.replace(/\.(png|jpe?g)$/i, "-480w.webp");
    const info = await sharp(input)
      .resize({ width: SMALL_WIDTH, withoutEnlargement: true })
      .webp({ quality: 82 })
      .toFile(output);
    console.log(`${rel} -> ${path.basename(output)} (${info.width}x${info.height}, ${(info.size / 1024).toFixed(1)} KB)`);
  }
})().catch(err => {
  console.error(err);
  process.exit(1);
});
